def transform(grid):
    n = len(grid)
    if not n or any(len(row) != n for row in grid):
        raise ValueError("expected a non-empty square grid")

    def transpose(a):
        return [list(row) for row in zip(*a)]

    def flip_h(a):
        return [row[::-1] for row in a]

    def flip_v(a):
        return a[::-1]

    # Nine panels: a central copy, mirrored side panels, and transposed corners.
    panels = [
        [transpose(grid), flip_v(grid), transpose(grid)],
        [flip_h(grid), grid, flip_h(grid)],
        [flip_v(grid), flip_v(grid), transpose(grid)],
    ]
    return [sum((panels[br][bc][r] for bc in range(3)), [])
            for br in range(3) for r in range(n)]

